// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

import React, { useState, useEffect } from "react";
import { FormattedMessage } from "react-intl";
import { SingleDatePicker } from "react-dates";
import Pagination2 from "react-js-pagination";
import { useHistory } from "react-router-dom";
import Loader from "react-loader-spinner";
import moment from "moment";
import Select from "react-select";
// Redux
import { connect } from "react-redux";
import { fetchAffiliatePostingReport, downloadAffiliatePostingReport } from "../../../../actions/filesets";

import { getRegionCodes, fetchAffiliatesNamesAndCodes } from "../../../../actions/affiliates";

// Utils

// Components
import { Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import PostingTable from "../../../../components/PostingTable";

// query string
const queryString = require("query-string");

const AffiliatePostingReport = ({
	// function props
	getRegionCodes,
	downloadAffiliatePostingReport,
	fetchAffiliatesNamesAndCodes,
	fetchAffiliatePostingReport,
	// query string props
	location                       : { search: queryParams }, // gets the query string from props.search and save it as queryParams
	// state variables props
	download_status,
	regionCodes,
	selectedAffiliateCode,
	posting_report,
	posting_report_error,
}) => {
	// QUERY STRING VARIABLES
	// let { affiliateCode } = queryString.parse(queryParams);
	let { settlementDate } = queryString.parse(queryParams);
	let { page } = queryString.parse(queryParams);
	let regionCode = queryString.parse(queryParams)["region-code"];

	const history = useHistory(); // save react router history to history
	const [ focused, setFocused ] = useState(false);
	const [ startDate, setStartDate ] = useState(moment(settlementDate));
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	// React select ony takes objec e.g {label: "USD": value:"USD"} so this construct achieves this but is also dynamic to what ever is passed as the region code in the query string.
	const [ selectedRegion, setSelectedRegion ] = useState({
		label : regionCode,
		value : regionCode,
	});
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setSelectedRegion({
				label : regionCode,
				value : regionCode,
			});
		},
		[ regionCode ],
	);
	const [ activePage, setActivePage ] = useState(parseInt(page));
	useEffect(
		() => {
			// console.log("PAGE NUMBER", page, activePage);
			// handles page change via url
			setActivePage(parseInt(page));
		},
		[ page ],
	);

	// Handle Header Issuer Code Change
	useEffect(
		() => {
			const pageQuery = page - 1;
			fetchAffiliatePostingReport(settlementDate, regionCode, pageQuery);
		},
		[ selectedAffiliateCode ],
	);

	// Use Effect Handles General Updates
	useEffect(
		() => {
			console.log("AFFILIATE POSTING PARAM", posting_report);
			const pageQuery = page - 1;
			getRegionCodes();
			fetchAffiliatesNamesAndCodes();
			fetchAffiliatePostingReport(settlementDate, regionCode, pageQuery);
		},
		[ queryParams ],
	);

	const handlePageChange = (pageNumber) => {
		history.push(
			`/interaffiliate/settlement/reports/affiliate-posting-report?settlementDate=${settlementDate}&region-code=${regionCode}&page=${pageNumber}`,
		);
		setActivePage(pageNumber);
	};

	const handleSubmitDate = () => {
		//handle Submite Date
		// handle submit of new selected date
		let date1 = moment(startDate).format();
		if (date1.includes("T")) {
			let extract = date1.split("T");
			date1 = extract[0];
			history.push(
				`/interaffiliate/settlement/reports/affiliate-posting-report?settlementDate=${date1}&region-code=${selectedRegion.label}&page=${page}`,
			); // redirect to new page programattically when new date is submitted.
		}
	};

	let SelectRegion = [];
	SelectRegion =
		regionCodes &&
		regionCodes.map((region) => {
			return { label: region.code, value: region };
		});

	const SettlemenReportHeader = [
		"Branch",
		"Home Branch",
		"Constant",
		"Constant1",
		"Fcy Amount",
		"Gl Account No",
		"Dr Cr",
		"Gl Account Branch",
		"Fcy Currency",
		"Lcy Amount",
		"Tx Code",
		"Date",
		"Rate",
		"Constant2",
		"Narration",
	];

	return (
		<div className='animated fadeIn'>
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									<FormattedMessage id='Issuer Report ' defaultMessage='Issuer Report ' />
									{settlementDate}
									<FormattedMessage id=' Source Item' defaultMessage=' Source Item' />
								</React.Fragment>
							</strong>

							<div style={{ width: "73%" }} className={"d-flex justify-content-end align-items-center"}>
								<React.Fragment>
									<span className={"mx-1"}>
										<SingleDatePicker
											showDefaultInputIcon={true}
											date={startDate} // momentPropTypes.momentObj or null
											onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
											focused={focused} // PropTypes.bool
											onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
											id='your_unique_id' // PropTypes.string.isRequired,
											isOutsideRange={() => false}
											numberOfMonths={1}
										/>
									</span>
									<span style={{ width: "14%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setSelectedRegion(selectedOption)}
											value={selectedRegion}
											options={SelectRegion && SelectRegion}
										/>
									</span>
									<Button
										style={{
											padding                : "9px",
											borderTopLeftRadius    : "0px",
											borderBottomLeftRadius : "0px",
										}}
										className={"btn-sm mx-1"}
										onClick={handleSubmitDate}
										color='primary'
									>
										{" "}
										<FormattedMessage id='Submit' defaultMessage='Submit' />
									</Button>
								</React.Fragment>
								<React.Fragment>
									<Button
										className={"btn-sm ml-1"}
										style={{ padding: "8px" }}
										color='success'
										onClick={(e) => downloadAffiliatePostingReport(settlementDate, regionCode)}
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-download' />&nbsp;
											{download_status ? (
												<Loader
													type='ThreeDots'
													color='#FFF'
													height={20}
													width={20}
													style={{ textAlign: "center" }}
												/>
											) : (
												<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
											)}
										</span>
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!posting_report_error &&
							!posting_report && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle Errors */}
							{!posting_report &&
							posting_report_error &&
							posting_report_error.data && (
								<article className='d-flex justify-content-center align-items-center'>
									<p className='text-center text-danger'>
										<FormattedMessage
											id={posting_report_error.data.message}
											defaultMessage={posting_report_error.data.message}
										/>
									</p>
								</article>
							)}

							{/* Handle display content */}
							{posting_report &&
							posting_report.data && (
								<Table2 hover bordered striped responsive size='sm' style={{ minWidth: "370%" }}>
									<thead>
										<PostingTableHeader
											headerType={"array"}
											headerPayload={SettlemenReportHeader}
										/>
									</thead>
									<tbody>
										<PostingTable
											tableName={"settlement-report"}
											dataRecords={
												posting_report && posting_report.data ? posting_report.data.content : []
											}
										/>
									</tbody>
								</Table2>
							)}

							{/* Handle Pagination */}
							{posting_report &&
							posting_report.data &&
							posting_report.data.content.length > 0 && (
								<nav>
									<Pagination2
										activePage={activePage}
										itemsCountPerPage={posting_report.data.size}
										totalItemsCount={(posting_report && posting_report.data.totalElements) || null}
										pageRangeDisplayed={20}
										onChange={handlePageChange}
									/>
								</nav>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		selectedAffiliateCode : state.fileSets.selectedAffiliateCode,
		download_status       : state.fileSets.download_status,
		posting_report        : state.fileSets.posting_report,
		posting_report_error  : state.fileSets.posting_report_error,
		regionCodes           : state.affiliates.region_codes,
		allAffiliates         : state.affiliates.affiliatesNamesAndCodes,
	};
};

export default connect(mapStateToProps, {
	fetchAffiliatePostingReport,
	downloadAffiliatePostingReport,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
})(AffiliatePostingReport);
